{{ ns.val if ns.val is not none else state_attr('weather.forecast_domov','wind_speed')|float(0) }}

variables.forecast_cloud:
{% set target_ts=next_comfort_ts|float(default=none) %}
{% set fc=(ph_hourly.get('weather.forecast_domov',{}).get('forecast',[]) if ph_hourly is mapping else []) %}
{% set ns=namespace(diff=999999999,val=none) %}
{% if target_ts is not none %}
  {% for f in fc %}
