{{ ns.val if ns.val is not none else state_attr('weather.forecast_domov','cloud_coverage')|float(50) }}

variables.lead_minutes:
{% set current=states(temp_sensor)|float(default=none) %}
{% set target=states(comfort_helper)|float(default=none) %}
{% set out=forecast_temp|float(10) %}
{% set wind=forecast_wind|float(0) %}
{% set cloud=forecast_cloud|float(50) %}
{% set rate=rate_cph|float(1.5) %}
{% set bias=bias_min|float(0) %}
{% set samples=learning_samples|int(0) %}
{% set delivery=delivery_score|float(0) %}
{% if current is none or target is none or target > 27 or target <= current + 0.2 or rate <= 0 %}
0
{% else %}
  {% set gap=target-current %}
  {% set base=(gap/rate*60) %}
  {% set cold=1.30 if out < 0 else 1.20 if out < 5 else 1.10 if out < 10 else 1.0 %}
  {% set windf=0.12 if wind >= 25 else 0.07 if wind >= 15 else 0.03 if wind >= 8 else 0 %}
  {% set sunf=-0.05 if cloud < 25 and out > 5 else 0 %}
  {% set deliveryf=0.10 if samples >= 2 and delivery < 40 else 0.05 if samples >= 2 and delivery < 60 else 0 %}
  {% set raw=base*(cold+windf+sunf+deliveryf)+10+bias %}
  {{ [[raw|round(0),0]|max,180]|min }}
{% endif %}

variables.coast_text:
{% if coast_samples|int > 0 %}
{% set stop=(states(comfort_helper)|float(0))-(coast_gain|float) %}
dojezd {{ coast_gain|round(2)|string|replace('.',',') }} °C · Shadow stop ~{{ stop|round(1)|string|replace('.',',') }} °C
{% else %}dojezd se učí{% endif %}

variables.status_text:
{% set current=states(temp_sensor)|float(default=none) %}
{% set target=states(comfort_helper)|float(default=none) %}
{% set nts=next_comfort_ts|float(default=none) %}
{% set lead=lead_minutes|float(0) %}
{% if not is_state(enable_helper,'on') %}
rozvrh vypnutý · model chyba {{ previous_error }} · MAE {{ mae_text }}
{% elif is_state(schedule_helper,'on') %}
komfort aktivní {{ (target|string|replace('.',',')) ~ ' °C' if target is not none else '' }} · model chyba {{ previous_error }} · MAE {{ mae_text }}
{% elif current is none or target is none %}
chybí teplotní data · model chyba {{ previous_error }}
{% elif target > 27 %}
model blokován: komfort {{ target|string|replace('.',',') }} °C
{% elif nts is none %}
čekám na další okno · model chyba {{ previous_error }} · MAE {{ mae_text }}
{% else %}
  {% set start=nts-lead*60 %}
cíl {{ nts|timestamp_custom('%H:%M',true) }} / {{ target|string|replace('.',',') }} °C · start {{ start|timestamp_custom('%H:%M',true) }} · {{ lead|round(0)|int }} min · model chyba {{ previous_error }} · MAE {{ mae_text }} · {{ coast_text|trim }}
{% endif %}
